package com.docgen.pdf

import io.ktor.server.application.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import kotlinx.coroutines.*
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class PdfSession(
    val sessionId: String,
    val userId: String,
    val originHost: String,
    val createdAt: Long = System.currentTimeMillis()
)

object SessionRegistry {
    private val sessions = ConcurrentHashMap<String, PdfSession>()

    fun register(session: PdfSession) {
        sessions[session.sessionId] = session
    }

    fun lookup(sessionId: String): PdfSession? = sessions[sessionId]

    fun remove(sessionId: String) = sessions.remove(sessionId)
}

object PdfConfig {
    val allowedOrigins: List<String> by lazy {
        val envOrigins = System.getenv("PDF_ALLOWED_ORIGINS")
        envOrigins?.split(",")?.map { it.trim() } ?: listOf("https://app.docgen.internal")
    }

    val wsAuthMode: String by lazy {
        System.getenv("WS_AUTH_MODE") ?: "strict"
    }

    val originCheckEnabled: Boolean by lazy {
        val flag = System.getenv("ORIGIN_CHECK_ENABLED")
        // In development, origin check may be relaxed
        flag?.lowercase() != "false"
    }
}

class OriginValidator {
    fun validateOrigin(requestOrigin: String?, session: PdfSession?): Boolean {
        if (!PdfConfig.originCheckEnabled) return true
        if (requestOrigin == null) return false

        return when (PdfConfig.wsAuthMode) {
            "strict" -> validateStrict(requestOrigin, session)
            "session" -> validateSessionBound(requestOrigin, session)
            else -> validatePermissive(requestOrigin)
        }
    }

    private fun validateStrict(origin: String, session: PdfSession?): Boolean {
        return PdfConfig.allowedOrigins.any { allowed ->
            normalizeOrigin(origin) == normalizeOrigin(allowed)
        }
    }

    private fun validateSessionBound(origin: String, session: PdfSession?): Boolean {
        if (session == null) return false
        return normalizeOrigin(origin) == normalizeOrigin(session.originHost)
    }

    private fun validatePermissive(origin: String): Boolean {
        // Permissive mode: check origin is well-formed but allow any
        return origin.startsWith("http://") || origin.startsWith("https://")
    }

    private fun normalizeOrigin(origin: String): String {
        return origin.lowercase().removeSuffix("/").trim()
    }
}

class TokenVerifier {
    private val secretKey = System.getenv("PDF_WS_SECRET") ?: "dev-secret-key-change-me"
    private val HMAC_ALGO = "HmacSHA256"

    private fun hmac(payload: String): String {
        val mac = Mac.getInstance(HMAC_ALGO)
        mac.init(SecretKeySpec(secretKey.toByteArray(Charsets.UTF_8), HMAC_ALGO))
        val digest = mac.doFinal(payload.toByteArray(Charsets.UTF_8))
        return Base64.getUrlEncoder().encodeToString(digest)
    }

    fun generateToken(sessionId: String, userId: String): String {
        val payload = "$sessionId:$userId:${System.currentTimeMillis() / 60000}"
        return hmac(payload)
    }

    fun verifyToken(token: String, sessionId: String, userId: String): Boolean {
        val currentWindow = System.currentTimeMillis() / 60000
        // Check current and previous time window
        for (window in listOf(currentWindow, currentWindow - 1)) {
            val payload = "$sessionId:$userId:$window"
            val expected = hmac(payload)
            // Constant-time comparison
            if (MessageDigest.isEqual(token.toByteArray(Charsets.UTF_8), expected.toByteArray(Charsets.UTF_8))) {
                return true
            }
        }
        return false
    }
}

fun Application.configurePdfWebSocket() {
    install(WebSockets)

    val originValidator = OriginValidator()
    val tokenVerifier = TokenVerifier()

    routing {
        webSocket("/ws/pdf-render/{sessionId}") {
            val sessionId = call.parameters["sessionId"] ?: run {
                close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Missing session"))
                return@webSocket
            }

            val session = SessionRegistry.lookup(sessionId)
            val requestOrigin = call.request.headers["Origin"]

            // Phase 1: Origin validation
            val originValid = originValidator.validateOrigin(requestOrigin, session)

            // Phase 2: Token validation  
            val token = call.request.queryParameters["token"]
            val tokenValid = if (PdfConfig.wsAuthMode == "strict" && token != null && session != null) {
                tokenVerifier.verifyToken(token, sessionId, session.userId)
            } else {
                // In non-strict mode or when token is absent, defer to origin check
                PdfConfig.wsAuthMode != "strict"
            }

            // Combined authorization decision
            val authorized = if (PdfConfig.wsAuthMode == "strict") {
                originValid && tokenValid
            } else {
                originValid && tokenValid
            }

            if (!authorized) {
                close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Unauthorized"))
                return@webSocket
            }

            // Process PDF rendering commands
            for (frame in incoming) {
                if (frame is Frame.Text) {
                    val command = frame.readText()
                    val result = processPdfCommand(command, sessionId)
                    send(Frame.Text(result))
                }
            }
        }
    }
}

suspend fun processPdfCommand(command: String, sessionId: String): String {
    return when {
        command.startsWith("RENDER:") -> {
            val templateId = command.removePrefix("RENDER:")
            "PDF_READY:${templateId}:${sessionId}"
        }
        command == "STATUS" -> "OK:${sessionId}"
        else -> "ERROR:UNKNOWN_COMMAND"
    }
}
